Action: run_sql({'query': "SELECT \n    COUNT(DISTINCT i.inspection_id) as total_inspections,\n    AVG(i.inspection_score) as avg_score,\n    MAX(i.inspection_score) as max_score,\n    MIN(i.inspection_score) as min_score,\n    SUM(CASE WHEN vc.critical THEN 1 ELSE 0 END) * 1.0 / COUNT(DISTINCT i.inspection_id) as avg_critical_per_insp,\n    COUNT(v.violation_id) * 1.0 / COUNT(DISTINCT i.inspection_id) as avg_violations_per_insp\nFROM establishment_keys ek\nJOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\nLEFT JOIN violations v ON i.inspection_id = v.inspection_id\nLEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nWHERE ek.name ILIKE '%IN N OUT%'"})

