Action: run_sql({'query': "WITH ranked_inspections AS (\n    SELECT \n        ek.city,\n        ek.address,\n        i.inspection_date,\n        i.inspection_score,\n        COUNT(v.violation_id) as total_violations,\n        COUNT(CASE WHEN vc.critical THEN 1 END) as critical_violations,\n        ROW_NUMBER() OVER (PARTITION BY ek.slchd_establishment_key ORDER BY i.inspection_date DESC) as rn\n    FROM establishment_keys ek\n    JOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\n    LEFT JOIN violations v ON i.inspection_id = v.inspection_id\n    LEFT JOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\n    WHERE ek.name ILIKE '%IN N OUT%'\n    GROUP BY ek.slchd_establishment_key, ek.city, ek.address, i.inspection_id, i.inspection_date, i.inspection_score\n)\nSELECT city, address, inspection_date, inspection_score, total_violations, critical_violations\nFROM ranked_inspections\nWHERE rn = 1\nORDER BY city"})

