Action: run_sql({'query': "SELECT \n    vc.code_text,\n    vc.critical,\n    v.violation_description,\n    v.violation_phr,\n    COUNT(*) as citation_count\nFROM establishment_keys ek\nJOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\nJOIN violations v ON i.inspection_id = v.inspection_id\nJOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nWHERE ek.name ILIKE '%IN N OUT%'\nGROUP BY vc.code_text, vc.critical, v.violation_description, v.violation_phr\nORDER BY citation_count DESC\nLIMIT 15"})

