Action: run_sql({'query': "WITH recent AS (\n    SELECT \n        ek.city as location,\n        i.inspection_score as most_recent_score,\n        ROW_NUMBER() OVER (PARTITION BY ek.city ORDER BY i.inspection_date DESC) as rn\n    FROM establishment_keys ek\n    JOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\n    WHERE ek.name ILIKE '%IN N OUT%'\n)\nSELECT \n    ek.city as location,\n    ROUND(AVG(i.inspection_score), 1) as avg_score,\n    MAX(CASE WHEN r.rn = 1 THEN r.most_recent_score END) as latest_score\nFROM establishment_keys ek\nJOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\nJOIN recent r ON ek.city = r.location\nWHERE ek.name ILIKE '%IN N OUT%'\nGROUP BY ek.city\nORDER BY avg_score"})

