Action: run_sql({'query': "WITH recent AS (\n    SELECT \n        ek.city as location,\n        i.inspection_score as latest_score,\n        ROW_NUMBER() OVER (PARTITION BY ek.city ORDER BY i.inspection_date DESC) as rn\n    FROM establishment_keys ek\n    JOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\n    WHERE ek.name ILIKE '%IN N OUT%'\n)\nSELECT \n    ek.city as location,\n    ROUND(AVG(i.inspection_score), 1) as avg_inspection_score,\n    r.latest_score\nFROM establishment_keys ek\nJOIN inspections i ON ek.slchd_establishment_key = i.slchd_establishment_key\nJOIN recent r ON ek.city = r.location AND r.rn = 1\nWHERE ek.name ILIKE '%IN N OUT%'\nGROUP BY ek.city, r.latest_score\nORDER BY avg_inspection_score"})

